{
  "probability": 0.89,
  "range_low": 0.82,
  "range_high": 0.96,
  "summary": [
    "Bayesian posterior probability for a two-thirds majority in the 2026 Hungarian election is 0.89.",
    "Anchor is the historical base-rate of ~0.44 for achieving 2/3 majorities under current rules; updates raise probability due to favorable dynamics.",
    "Key upward drivers: opposition unity around Tisza and structural electoral rules; market signals add mild support.",
    "Downward pressures: poll volatility and vote-splitting risk limit upside and introduce uncertainty."
  ],
  "confidence": "high",
  "narrative": "Starting from a baseline anchor around 0.44, strong pushes from a unified opposition and structural rules raise the odds of a two-thirds majority. Persistent poll divergence and fragmentation cap upside, while financial market signals slightly reinforce the possibility, yielding a calibrated posterior near 0.89 with a wide-but-not-immune uncertainty band.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base-rate for achieving a two-thirds majority in Hungary’s post-1990 parliaments under current electoral rules (about 4 of 9 elections, ~0.44). Used as the calibration anchor for the posterior."
    },
    "factor_updates": [
      {
        "factor": "Opposition unity around the Tisza platform",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Unified anti-Fidesz front increases seat consolidation potential, raising chances of crossing the 133-seat threshold."
      },
      {
        "factor": "Structural electoral rules favoring large blocs",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Winner compensation and district design historically magnify large majorities, boosting the odds of a 2/3 outcome if a large bloc mobilizes."
      },
      {
        "factor": "Polls showing split or no stable path to a 2/3 majority",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Divergence reduces confidence in a decisive majority and tempers the probability mass toward a 2/3 outcome."
      },
      {
        "factor": "Market and investor signals pricing a non-Fidesz outcome",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Forint appreciation and market commentary reflect expectations of potential government change, adding incremental upside pressure."
      },
      {
        "factor": "Historical base-rate context as anchor",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Acts as a baseline reference; not a decisive driver but essential for calibration."
      }
    ],
    "synthesis_rationale": "The posterior was formed by adjusting the anchor upward for strong drivers (opposition unity, structural rules) and downward for countervailing factors (poll heterogeneity, fragmentation). The combination yields a high but calibrated probability of 0.89, with an uncertainty range reflected in range_low/high to account for potential correlations among factors and model limitations"
  }
}

{
  "probability": 0.89,
  "range_low": 0.80,
  "range_high": 0.98,
  "summary": [
    "The posterior probability for any party or coalition to win a two-thirds (133 of 199) seats in 2026 Hungary is 0.89, per Bayesian update from a 0.44 anchor.",
    "Upward updates come from opposition unity around the Tisza platform and structural rules that favor large blocs.",
    "Polls are mixed, but some markets and forecasts show a non-Fidesz path as plausible, supporting the upshift.",
    "Persistent poll volatility and potential vote-splitting keep the outcome contingent and prevent a guaranteed 2/3."
  ],
  "confidence": "high",
  "narrative": "Starting from a 0.44 historical anchor, consolidation of anti-Fidesz support and structural rules boost the odds of a 2/3 majority. Despite mixed polls, market signals and the expected scale of unified opposition push the posterior toward 0.89, though fragmentation risks and turnout uncertainties leave residual caveats.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "historical base-rate for achieving a two-thirds majority under post-1990 Hungary elections (roughly 4 of 9 elections)"
    },
    "factor_updates": [
      {
        "factor": "Opposition unity around the Tisza platform",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "A unified anti-Fidesz bloc increases seat consolidation and the probability of reaching the 133-seat threshold."
      },
      {
        "factor": "Structural electoral rules favoring large blocs",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Winner compensation and district design historically amplify majorities, supporting a 2/3 outcome when coalitions mobilize."
      },
      {
        "factor": "Polls/prediction markets tilting toward opposition",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Market and poll signals show at times an opposition lead or narrowed gap, raising odds of a non-Fidesz majority."
      },
      {
        "factor": "Poll volatility and lack of stable consensus",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Divergent polling reduces confidence in a decisive 2/3 path and introduces risk of fragmentation."
      },
      {
        "factor": "Market/economic signaling of potential governmental change",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Economic expectations (e.g., forint movement) reflect broader bets on policy shifts, marginally increasing posterior odds."
      }
    ],
    "synthesis_rationale": "Starting from the 0.44 anchor, the strong pull from opposition unity and structural rules yields a substantial upward adjustment. The mixed polls and fragmentation risk temper the gain, while markets provide additional, albeit modest, evidence of possible change. The final 0.89 posterior reflects this balance, acknowledging correlation among factors may reduce the effective impact of multiple upward updates"
  }
}

{
  "probability": 0.65,
  "range_low": 0.55,
  "range_high": 0.75,
  "summary": [
    "Anchored to historical frequency of two-thirds majorities (~0.44 under current rules).",
    "Strong upward case from potential opposition unity (Tisza) and structural rules that amplify large blocs.",
    "Moderate downward pressure from poll volatility and vote-splitting risks (Our Homeland entry)."
  ],
  "confidence": "medium",
  "narrative": "Starting from a 0.44 anchor based on history under the current electoral system, the strongest updates push probability toward a 2/3 majority if opposition unity materializes and rules amplify majorities. However, mixed polls and potential fragmentation keep the probability from rising too high; I estimate 0.65 with a 0.55–0.75 range, noting important caveats about turnout and coalition dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Base-rate anchor from post-1990 Hungarian elections showing 2/3 majorities in 2010, 2014, 2018, and 2022 (4/9), under current rules."
    },
    "factor_updates": [
      {
        "factor": "Opposition unity around the Tisza platform",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Unified anti-Fidesz vote increases seat share, potentially crossing the 133-seat threshold; multiple forecasts indicate momentum for Tisza."
      },
      {
        "factor": "Electoral rules that amplify majorities (winner compensation and district design)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Structural features historically boost large blocs; consolidated coalitions can translate votes into outsized seat gains."
      },
      {
        "factor": "Prediction markets and polls tilting toward opposition",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Market bets and some polls show opposition leads or narrowing gaps, increasing probability mass on a 2/3 outcome relative to the anchor."
      },
      {
        "factor": "Poll volatility and lack of a stable consensus",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Divergent polls reduce confidence in a decisive majority path, tempering upside pressure from unity and rules."
      },
      {
        "factor": "Our Homeland entering parliament (vote-splitting risk)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Additional entrants can fragment anti-Fidesz support, hindering any single bloc from reaching 2/3."
      }
    ],
    "synthesis_rationale": "From a base of 0.44, the strongest updates push probability upward due to potential opposition unity and favorable rules, while downward pressures from poll volatility and fragmentation counterbalance. The net effect yields a calibrated point estimate of 0.65 with a 0.55–0.75 plausible range, reflecting substantial uncertainty about turnout, final coalitions, and how votes translate into seats. Calibration recognizes that outcomes near the threshold are highly sensitive to small shifts in vote shares and seat allocation."
  }
}
